package main

import (
    "errors"
    "fmt"
)

func Divide(a, b int) (int, error) {
    if b == 0 {
        return 0, errors.New("деление на ноль")
    }
    return a / b, nil
}

func main() {
    if res, err := Divide(10, 2); err == nil {
        fmt.Println(res)
    }
    _, err := Divide(1, 0)
    fmt.Println(err)
}

package main

import (
    "fmt"
    "strconv"
)

func double(s string) (int, error) {
    n, err := strconv.Atoi(s)
    if err != nil {
        return 0, err
    }
    return n * 2, nil
}

func main() {
    for _, s := range []string{"21", "го"} {
        n, err := double(s)
        if err != nil {
            fmt.Println("ошибка")
            continue
        }
        fmt.Println(n)
    }
}
